export function validateLYMPHATICSeed(): void {
  const slugs = new Set(
    LYMPHATIC_STRUCTURES.map((structure) => structure.slug),
  );
  if (slugs.size !== LYMPHATIC_STRUCTURES.length) {
    throw new Error(
      'Lymphatic system seed contains duplicate structure slugs.',
    );
  }
  const meshNames = new Set(
    LYMPHATIC_STRUCTURES.map((structure) => structure.meshName),
  );
  if (meshNames.size !== LYMPHATIC_STRUCTURES.length) {
    throw new Error('Lymphatic system seed contains duplicate mesh names.');
  }
  if (LYMPHATIC_STRUCTURES.length !== 3) {
    throw new Error('Lymphatic system seed must contain exactly 3 structures.');
  }
  for (const structure of LYMPHATIC_STRUCTURES) {
    for (const relatedSlug of structure.relatedSlugs) {
      if (!slugs.has(relatedSlug)) {
        throw new Error(
          `Structure "${structure.slug}" references unknown related slug "${relatedSlug}".`,
        );
      }
    }
    if (structure.references.length === 0) {
      throw new Error(`Structure "${structure.slug}" has no references.`);
    }
    if (
      structure.meshName !== null &&
      !/^[a-z0-9_]+$/.test(structure.meshName)
    ) {
      throw new Error(
        `Structure "${structure.slug}" has an invalid mesh name "${structure.meshName}".`,
      );
    }
  }
}
